package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.WebsiteUrlVO;

class WebsiteUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of website url of user profile")
  void test_website_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    WebsiteUrlValueHolder<Object> value = new WebsiteUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.websiteUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getWebsiteUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getWebsiteUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.websiteUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getWebsiteUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getWebsiteUrl().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of website url of user profile")
  void test_website_url_value_holder_assign_value_object() {
    Object holder = new Object();
    WebsiteUrlValueHolder<Object> value = new WebsiteUrlValueHolder<>(holder);
    WebsiteUrlVO vo = WebsiteUrlVO.from("one");
    Assertions.assertFalse(value.getWebsiteUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.websiteUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWebsiteUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.websiteUrl(Optional.empty()));
    Assertions.assertFalse(value.getWebsiteUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.websiteUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWebsiteUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of website url of user profile against the original")
  void test_website_url_value_holder_read() {
    Object holder = new Object();
    WebsiteUrlValueHolder<Object> value = new WebsiteUrlValueHolder<>(holder);
    WebsiteUrlVO vo = WebsiteUrlVO.from("one");
    WebsiteUrlVO other = WebsiteUrlVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getWebsiteUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWebsiteUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWebsiteUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.websiteUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWebsiteUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWebsiteUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of website url of user profile")
  void test_website_url_value_holder_unset() {
    Object holder = new Object();
    WebsiteUrlValueHolder<Object> value = new WebsiteUrlValueHolder<>(holder);
    WebsiteUrlVO vo = WebsiteUrlVO.from("one");
    value.websiteUrl(vo);
    Assertions.assertSame(holder, value.unsetWebsiteUrlIfMatches("websiteUrl_other"));
    Assertions.assertTrue(value.getWebsiteUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWebsiteUrlIfMatches("websiteUrl"));
    Assertions.assertFalse(value.getWebsiteUrlValue().isPresent(),
        "The field name must clear the value");
    value.websiteUrl(vo);
    Assertions.assertSame(holder, value.unsetWebsiteUrl());
    Assertions.assertFalse(value.getWebsiteUrlValue().isPresent(), "Unset must clear the value");
  }
}
